"""Overnight run: in-domain DeBERTa baseline, seed 21, 3 epoch(s), no checkpoint output."""
import base64, os, subprocess, sys

SCRIPT = base64.b64decode("").decode()
open("/kaggle/working/colab_baselines.py", "w").write(SCRIPT)
subprocess.run(["git", "clone", "--depth", "1",
                "https://github.com/aashish254/myna.git", "/kaggle/working/myna"], check=True)

cmd = [sys.executable, "/kaggle/working/colab_baselines.py",
       "--data-dir", "/kaggle/working/myna/data/decision-v2-pilot",
       "--seeds", "21", "--epochs", "3",
       "--batch", "8", "--accum", "2", "--max-len", "512",
       "--lr-head", "1e-4", "--skip-ood", "--save-every", "0",
       "--out", "/kaggle/working/results", "--device", "cuda"]
print("running:", " ".join(cmd), flush=True)
subprocess.run(cmd, check=True)
print("outputs:", sorted(os.listdir("/kaggle/working/results")), flush=True)
